SELECT id, enterprise_id, owner_user_id, JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.runId')) AS run_id,
lease_owner, lease_version, lease_until FROM background_job
WHERE kind = 'run' AND status = 'leased' AND lease_until <= #{now} ORDER BY lease_until, id LIMIT #{limit}

SELECT id, JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.lastEventBatchId')) AS last_event_batch_id,
JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.lastEventBatchHash')) AS last_event_batch_hash
FROM background_job WHERE id = #{id}

